transforms.code:

try:
	int(value)
	return 'Unknown State (%s)'%value
except:
	return value or 'Unknown state'

default = {
			"availability": {"color": '#d5d5d5', "fontColor": "", "value": 0},
			"oee": {"color": '#d5d5d5', "fontColor": "", "value": 0},
			"performance": {"color": '#d5d5d5', "fontColor": "", "value": 0},
			"quality": {"color": '#d5d5d5', "fontColor": "", "value": 0}
			}

if value['tagInfo'] is None: return default
val = value['tagInfo']

if not value['assetInfo']['assetId'] or (val['infeedCount'] == 0 and val['outfeedCount'] == 0 and val['runtimeSecs'] == 0 and val['unplannedDowntimeSecs'] == 0):
	return default

oee = val['availability'] * min(val['performance'], 1.0) * val['quality']
oeeColors = system.kanoa.event.getOEEColors({'assetPath': value['assetInfo']['assetPath']}, oee, val['availability'], min(val['performance'], 1.0), val['quality'])
return {
			"availability": {"color": oeeColors['availability'] or '#d5d5d5', "fontColor": "", "value": val['availability']},
			"oee": {"color": oeeColors['oee'] or '#d5d5d5', "fontColor": "", "value": oee},
			"performance": {"color": oeeColors['performance'] or '#d5d5d5', "fontColor": "", "value": val['performance']},
			"quality": {"color": oeeColors['quality'] or '#d5d5d5', "fontColor": "", "value": val['quality']}
		}


itemValues = {}	

for row in value:
	if row['itemName'] is None: continue
	if not itemValues.has_key(row['itemName']): itemValues[row['itemName']] = {'outfeedCount': 0, 'outfeedUnits': '', 'actualTime': 0, 'itemDescription':'', 'durationSecs': 0}

for row in value:
	if row['itemName'] is None: continue
	if not row['outfeedCount']: continue
	itemValues[row['itemName']]['outfeedCount'] += row['outfeedCount']
	itemValues[row['itemName']]['outfeedUnits'] = row['outfeedUnits']
	itemValues[row['itemName']]['durationSecs'] = row['durationSecs']
	itemValues[row['itemName']]['itemDescription'] = row['itemDescription']

return [{'value': {'itemName': k, 'itemDescription': v['itemDescription'], 'outfeedCount': v['outfeedCount'], 'outfeedUnits': v['outfeedUnits'], 'durationSecs': v['durationSecs'] }} for k,v in itemValues.items() if v['outfeedCount'] != 0]
